package rtpreceiver_test

import (
	"sync"
	"testing"
	"time"

	"github.com/pion/rtcp"
	"github.com/pion/rtp"
	"github.com/stretchr/testify/require"

	"github.com/bluenviron/gortsplib/v5/pkg/ntp"
	"github.com/bluenviron/gortsplib/v5/pkg/rtpreceiver"
)

// collectReports stores receiver reports generated by the receiver ticker.
type reportCollector struct {
	mu      sync.Mutex
	reports []*rtcp.ReceiverReport
}

func (c *reportCollector) push(pkt rtcp.Packet) {
	c.mu.Lock()
	defer c.mu.Unlock()
	c.reports = append(c.reports, pkt.(*rtcp.ReceiverReport))
}

func (c *reportCollector) snapshot() []*rtcp.ReceiverReport {
	c.mu.Lock()
	defer c.mu.Unlock()
	ret := make([]*rtcp.ReceiverReport, len(c.reports))
	copy(ret, c.reports)
	return ret
}

func (c *reportCollector) waitFor(t *testing.T, pred func(*rtcp.ReceiverReport) bool) *rtcp.ReceiverReport {
	t.Helper()

	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		for _, r := range c.snapshot() {
			if pred(r) {
				return r
			}
		}
		time.Sleep(10 * time.Millisecond)
	}
	t.Fatal("receiver report not generated in time")
	return nil
}

func rtpPacket(seq uint16, ts uint32) *rtp.Packet {
	return &rtp.Packet{
		Header: rtp.Header{
			Version:        2,
			Marker:         true,
			PayloadType:    96,
			SequenceNumber: seq,
			Timestamp:      ts,
			SSRC:           0xba9da416,
		},
		Payload: []byte{0x01, 0x02},
	}
}

// TestReceiverEpochReports verifies that Reset() starts a new reception epoch:
// cumulative counters survive while receiver reports and recent values describe
// only the current epoch. Report generation, packet processing and Stats run
// concurrently.
func TestReceiverEpochReports(t *testing.T) {
	baseTime := time.Date(2024, 1, 1, 0, 0, 0, 0, time.UTC)

	var clockMu sync.Mutex
	now := baseTime
	timeNow := func() time.Time {
		clockMu.Lock()
		defer clockMu.Unlock()
		return now
	}
	advance := func(d time.Duration) {
		clockMu.Lock()
		now = now.Add(d)
		clockMu.Unlock()
	}

	collector := &reportCollector{}

	rr := &rtpreceiver.Receiver{
		ClockRate: 90000,
		LocalSSRC: 0x65f83afb,
		// a reliable transport counts a gap immediately, which makes the
		// epoch-scoped loss deterministic.
		UnrealiableTransport: false,
		Period:               20 * time.Millisecond,
		TimeNow:              timeNow,
		WritePacketRTCP:      collector.push,
	}
	require.NoError(t, rr.Initialize())
	defer rr.Close()

	srFor := func(rtpTime uint32, at time.Time) *rtcp.SenderReport {
		return &rtcp.SenderReport{
			SSRC:    0xba9da416,
			NTPTime: ntp.Encode(at),
			RTPTime: rtpTime,
		}
	}

	// --- epoch 1 -----------------------------------------------------------

	pkts, lost := rr.ProcessPacket2(rtpPacket(1000, 90000), baseTime, true)
	require.Len(t, pkts, 1)
	require.Equal(t, uint64(0), lost)

	advance(40 * time.Millisecond)
	pkts, lost = rr.ProcessPacket2(rtpPacket(1001, 90360), timeNow(), true)
	require.Len(t, pkts, 1)
	require.Equal(t, uint64(0), lost)

	advance(time.Second)
	rr.ProcessSenderReport(srFor(90360, timeNow()), timeNow())

	epoch1Report := collector.waitFor(t, func(r *rtcp.ReceiverReport) bool {
		return len(r.Reports) == 1 && r.Reports[0].LastSenderReport != 0
	})
	require.Equal(t, uint32(1001), epoch1Report.Reports[0].LastSequenceNumber)
	require.Equal(t, uint32(0), epoch1Report.Reports[0].TotalLost)
	require.Equal(t, uint32(0xba9da416), epoch1Report.Reports[0].SSRC)
	require.Equal(t, uint32(0x65f83afb), epoch1Report.SSRC)
	require.NotZero(t, epoch1Report.Reports[0].LastSenderReport)

	stats1 := rr.Stats()
	require.NotNil(t, stats1)
	require.Equal(t, uint64(2), stats1.Received)
	require.Equal(t, uint64(0), stats1.Lost)
	require.Equal(t, uint16(1001), stats1.LastSequenceNumber)

	receivedTotal, lostTotal := rr.Totals()
	require.Equal(t, uint64(2), receivedTotal)
	require.Equal(t, uint64(0), lostTotal)

	// --- new epoch: the same sequence jump must not fabricate loss ---------

	advance(time.Second)
	rr.Reset()

	// no RTP in the new epoch: no report and empty recent values
	require.Nil(t, rr.Stats())
	receivedTotal, lostTotal = rr.Totals()
	require.Equal(t, uint64(2), receivedTotal, "cumulative received must survive the reset")
	require.Equal(t, uint64(0), lostTotal, "cumulative lost must survive the reset")

	reportsBefore := len(collector.snapshot())
	time.Sleep(60 * time.Millisecond)
	require.Len(t, collector.snapshot(), reportsBefore, "no receiver report must be emitted before the first RTP packet of an epoch")

	// RTP-Info style gate: late packets behind the threshold are dropped.
	rr.SetInitialSequenceThreshold(100)
	pkts, lost = rr.ProcessPacket2(rtpPacket(99, 800000), timeNow(), true)
	require.Nil(t, pkts)
	require.Equal(t, uint64(0), lost)
	require.Nil(t, rr.Stats(), "gated packets do not count")

	// first accepted packet of the new position: delivered immediately,
	// no fabricated 64k+ loss from the backwards sequence number jump.
	pkts, lost = rr.ProcessPacket2(rtpPacket(100, 800000), timeNow(), true)
	require.Len(t, pkts, 1)
	require.Equal(t, uint16(100), pkts[0].SequenceNumber)
	require.Equal(t, uint64(0), lost)

	advance(40 * time.Millisecond)
	pkts, _ = rr.ProcessPacket2(rtpPacket(101, 800360), timeNow(), true)
	require.Len(t, pkts, 1)

	// gap inside the epoch: the missing 102 is a real, epoch-scoped loss.
	advance(40 * time.Millisecond)
	reportsBeforeLoss := len(collector.snapshot())
	pkts, lost = rr.ProcessPacket2(rtpPacket(103, 800720), timeNow(), true)
	require.Equal(t, uint64(1), lost)
	require.Len(t, pkts, 1)

	// reports describe only the new epoch, not the cumulative client counters.
	epoch2Report := collector.waitFor(t, func(r *rtcp.ReceiverReport) bool {
		return len(r.Reports) == 1 && r.Reports[0].LastSequenceNumber == 103
	})
	require.Equal(t, uint32(103), epoch2Report.Reports[0].LastSequenceNumber,
		"extended sequence number restarts from the epoch's own base")
	require.Equal(t, uint32(1), epoch2Report.Reports[0].TotalLost,
		"report loss is epoch-scoped, not the client cumulative value")
	require.Equal(t, uint32(0), epoch2Report.Reports[0].LastSenderReport,
		"the previous epoch's sender report must not survive")

	// the first report emitted after the loss carries the epoch's fraction lost.
	var fractionReport *rtcp.ReceiverReport
	deadline := time.Now().Add(5 * time.Second)
	for time.Now().Before(deadline) {
		snap := collector.snapshot()
		if len(snap) > reportsBeforeLoss {
			fractionReport = snap[reportsBeforeLoss]
			break
		}
		time.Sleep(10 * time.Millisecond)
	}
	require.NotNil(t, fractionReport)
	require.NotZero(t, fractionReport.Reports[0].FractionLost)

	// a sender report of the new epoch is needed before LSR/DLSR get populated.
	advance(time.Second)
	rr.ProcessSenderReport(srFor(800720, timeNow()), timeNow())
	epoch2ReportWithSR := collector.waitFor(t, func(r *rtcp.ReceiverReport) bool {
		return len(r.Reports) == 1 &&
			r.Reports[0].LastSequenceNumber == 103 &&
			r.Reports[0].LastSenderReport != 0
	})
	require.Equal(t, uint32(103), epoch2ReportWithSR.Reports[0].LastSequenceNumber)
	require.Equal(t, uint32(1), epoch2ReportWithSR.Reports[0].TotalLost)

	stats2 := rr.Stats()
	require.NotNil(t, stats2)
	require.Equal(t, uint64(5), stats2.Received, "received keeps accumulating across epochs")
	require.Equal(t, uint64(1), stats2.Lost, "lost keeps accumulating across epochs")
	require.Equal(t, uint16(103), stats2.LastSequenceNumber, "recent values are epoch-scoped")
	require.Equal(t, uint32(800720), stats2.LastRTP)

	// PacketNTP is unavailable until the epoch's own sender report arrived:
	// before the SR above it would have returned false; now it maps using it.
	ntpTime, ok := rr.PacketNTP(800720)
	require.True(t, ok)
	require.True(t, ntpTime.Equal(timeNow()))

	// --- concurrency: reports, packets and stats together -----------------

	var wg sync.WaitGroup
	stop := make(chan struct{})

	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-stop:
				return
			default:
				rr.Stats()
				rr.Totals()
			}
		}
	}()

	wg.Add(1)
	go func() {
		defer wg.Done()
		seq := uint16(200)
		for {
			select {
			case <-stop:
				return
			default:
				rr.ProcessPacket2(rtpPacket(seq, 900000), timeNow(), true)
				seq++
			}
		}
	}()

	wg.Add(1)
	go func() {
		defer wg.Done()
		for {
			select {
			case <-stop:
				return
			default:
				rr.ProcessSenderReport(srFor(900000, timeNow()), timeNow())
			}
		}
	}()

	time.Sleep(200 * time.Millisecond)
	close(stop)
	wg.Wait()

	// the receiver keeps working and reporting after the concurrent stress.
	finalStats := rr.Stats()
	require.NotNil(t, finalStats)
	require.Greater(t, finalStats.Received, uint64(5))
	require.NotEmpty(t, collector.snapshot())
}

// TestReceiverEpochThresholdWraparound checks the uint16 modular gate,
// including the 65535 -> 0 wraparound.
func TestReceiverEpochThresholdWraparound(t *testing.T) {
	collector := &reportCollector{}

	rr := &rtpreceiver.Receiver{
		ClockRate:            90000,
		LocalSSRC:            0x65f83afb,
		UnrealiableTransport: true,
		Period:               time.Hour, // do not emit reports during the test
		TimeNow:              time.Now,
		WritePacketRTCP:      collector.push,
	}
	require.NoError(t, rr.Initialize())
	defer rr.Close()

	rr.SetInitialSequenceThreshold(65535)

	// behind the threshold, including a value that looks "ahead" as uint16
	pkts, lost := rr.ProcessPacket2(rtpPacket(65534, 1), time.Now(), true)
	require.Nil(t, pkts)
	require.Equal(t, uint64(0), lost)

	// the threshold itself is accepted
	pkts, lost = rr.ProcessPacket2(rtpPacket(65535, 2), time.Now(), true)
	require.Len(t, pkts, 1)
	require.Equal(t, uint64(0), lost)

	// 65535 -> 0 is forward motion (int16 modular difference is positive)
	rr.Reset()
	rr.SetInitialSequenceThreshold(65535)
	pkts, lost = rr.ProcessPacket2(rtpPacket(0, 3), time.Now(), true)
	require.Len(t, pkts, 1, "wraparound to 0 must pass the gate")
	require.Equal(t, uint64(0), lost)

	// once the first packet is accepted, the gate no longer intervenes:
	// an ordinary backwards duplicate is handled by the reorderer.
	pkts, lost = rr.ProcessPacket2(rtpPacket(0, 3), time.Now(), true)
	require.Nil(t, pkts)
	require.Equal(t, uint64(0), lost)

	require.Empty(t, collector.snapshot())
}
